const express = require('express');

const router = express.Router();

// pricing rules inlined directly in the route handlers (duplicated)
router.post('/quote', (req, res) => {
  const { unitPrice, quantity } = req.body;
  const subtotal = unitPrice * quantity;
  let discount = 0;
  if (quantity >= 100) discount = 0.2;
  else if (quantity >= 10) discount = 0.1;
  const total = Math.round(subtotal * (1 - discount) * 100) / 100;
  res.json({ subtotal: Math.round(subtotal * 100) / 100, discount, total });
});

router.post('/quote/bulk', (req, res) => {
  const out = req.body.map((item) => {
    const subtotal = item.unitPrice * item.quantity;
    let discount = 0;
    if (item.quantity >= 100) discount = 0.2;
    else if (item.quantity >= 10) discount = 0.1;
    const total = Math.round(subtotal * (1 - discount) * 100) / 100;
    return { subtotal: Math.round(subtotal * 100) / 100, discount, total };
  });
  res.json(out);
});

module.exports = router;

