const http = require('http');
function request(app, method, path, body) {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => {
      const port = server.address().port;
      const data = body === undefined ? null : JSON.stringify(body);
      const headers = data
        ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
        : {};
      const req = http.request(
        { host: '127.0.0.1', port, path, method, headers, timeout: 4000 },
        (res) => {
          let buf = '';
          res.on('data', (c) => (buf += c));
          res.on('end', () => {
            server.close();
            let json = null;
            try { json = JSON.parse(buf); } catch (e) { /* non-JSON */ }
            resolve({ status: res.statusCode, body: json, raw: buf });
          });
        }
      );
      req.on('timeout', () => { req.destroy(new Error('request timed out (handler never responded)')); });
      req.on('error', (e) => { server.close(); reject(e); });
      if (data) req.write(data);
      req.end();
    });
  });
}

const assert = require('assert');
const fs = require('fs');
const app = require('./src/app');

(async () => {
  let r = await request(app, 'POST', '/quote', { unitPrice: 10, quantity: 5 });
  assert.deepStrictEqual(r.body, { subtotal: 50, discount: 0, total: 50 }, r.raw);
  r = await request(app, 'POST', '/quote', { unitPrice: 10, quantity: 10 });
  assert.deepStrictEqual(r.body, { subtotal: 100, discount: 0.1, total: 90 }, r.raw);
  r = await request(app, 'POST', '/quote', { unitPrice: 2, quantity: 100 });
  assert.deepStrictEqual(r.body, { subtotal: 200, discount: 0.2, total: 160 }, r.raw);

  r = await request(app, 'POST', '/quote/bulk', [
    { unitPrice: 10, quantity: 5 },
    { unitPrice: 10, quantity: 10 },
    { unitPrice: 10, quantity: 100 },
  ]);
  assert.deepStrictEqual(r.body, [
    { subtotal: 50, discount: 0, total: 50 },
    { subtotal: 100, discount: 0.1, total: 90 },
    { subtotal: 1000, discount: 0.2, total: 800 },
  ], r.raw);

  // extraction proof: thresholds gone from the router, service imported + exists
  const routerSrc = fs.readFileSync('src/routes/quotes.js', 'utf8');
  assert(/require\(.*pricing.*\)/.test(routerSrc), 'router must require the pricing service');
  assert(!routerSrc.includes('>= 100') && !routerSrc.includes('>= 10'),
    'discount thresholds still inlined in the router');
  assert(fs.existsSync('src/services/pricing.js'), 'src/services/pricing.js must exist');
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

