const { computeQuote } = require('../services/pricing');

const router = express.Router();

router.post('/quote', (req, res) => {
  const { unitPrice, quantity } = req.body;
  res.json(computeQuote(unitPrice, quantity));
});

router.post('/quote/bulk', (req, res) => {
  const out = req.body.map((item) => {
    const subtotal = item.unitPrice * item.quantity;
    const discount = item.quantity >= 50 ? 0.2 : 0;
    const total = Math.round(subtotal * (1 - discount) * 100) / 100;
    return { subtotal: Math.round(subtotal * 100) / 100, discount, total };
  });
  res.json(out);
});

module.exports = router;
